# -*- coding: utf-8 -*-
"""Merge the mechanical funcref skeleton (uridium_funcref_raw.txt, generated by
bench codemap mode) with the manual Uridium analysis -> uridium_function_reference.txt

Structure:
  PART 1 - documented functions & anchors (manual analysis, sorted by address)
  PART 2 - additional recursive-map functions (mechanical info only, ROM noted)
"""
import re

D = {}
def F(addr, name, inp, outp, desc):
    D[addr] = (name, "FUNC", inp, outp, desc)
def DATA(addr, name, desc):
    D[addr] = (name, "DATA", "-", "-", desc)

