def main():
    # mechanical info from the recursive map: addr -> (callers, size, first)
    raw = open("uridium_funcref_raw.txt", encoding="utf-8").read().split("\n")
    mech = {}
    cur = None
    for ln in raw:
        m = re.match(r"FUNC \$([0-9A-F]{4})", ln)
        if m:
            cur = int(m.group(1), 16)
            mech[cur] = {"callers": [], "size": 0, "first": ""}
            continue
        if cur is None:
            continue
        mm = re.match(r"  CALLERS: (.*)", ln)
        if mm:
            mech[cur]["callers"] = [c for c in mm.group(1).split() if c.startswith("$")]
            continue
        mm = re.match(r"  SIZE   : (\d+) bytes", ln)
        if mm:
            mech[cur]["size"] = int(mm.group(1))
            continue
        mm = re.match(r"  FIRST  : (.*)", ln)
        if mm:
            mech[cur]["first"] = mm.group(1)

    out = []
    out.append("; URIDIUM - function reference (first-load 48K image, entry $F500)")
    out.append("; sources: recursive code map + linear sweep + dynamic trace + manual analysis")
    out.append("; per entry: CALLERS | IN | OUT | DESC")
    out.append("")

    out.append("=" * 74)
    out.append("PART 1 - DOCUMENTED FUNCTIONS AND ANCHORS")
    out.append("=" * 74)
    doc = 0
    for a in sorted(D):
        name, kind, inp, outp, desc = D[a]
        m = mech.get(a)
        out.append("")
        out.append("FUNC $%04X  %s" % (a, name))
        out.append("  KIND : " + kind)
        if m:
            cl = m["callers"]
            out.append("  CALLERS: " + (", ".join(cl[:6]) + (" (+%d more)" % (len(cl) - 6) if len(cl) > 6 else "") if cl else "(none - entered dynamically)"))
            out.append("  SIZE   : %d bytes mapped" % m["size"])
        out.append("  IN     : " + inp)
        out.append("  OUT    : " + outp)
        out.append("  DESC   : " + desc)
        doc += 1
    print("documented entries:", doc)

    # PART 2: recursive-map functions not already documented (in-image only)
    out.append("")
    out.append("=" * 74)
    out.append("PART 2 - ADDITIONAL FUNCTIONS FROM THE RECURSIVE CODE MAP")
    out.append("(mechanical entries - not yet analysed; $0000-$3FFF = ZX ROM)")
    out.append("=" * 74)
    extra = 0
    for a in sorted(mech):
        if a in D:
            continue
        m = mech[a]
        cl = m["callers"]
        cs = ", ".join(cl[:6]) + (" (+%d more)" % (len(cl) - 6) if len(cl) > 6 else "") if cl else "(entered dynamically)"
        region = "ROM" if a < 0x4000 else "RAM"
        out.append("")
        out.append("FUNC $%04X  (undocumented)  [%s]" % (a, region))
        out.append("  CALLERS: " + cs)
        out.append("  SIZE   : %d bytes mapped" % m["size"])
        out.append("  FIRST  : " + m["first"])
        extra += 1
    print("additional entries:", extra)

    open("uridium_function_reference.txt", "w", encoding="utf-8").write("\n".join(out))


if __name__ == "__main__":
    main()
